 function beginStep(x,y){if(x<1||y<1||x>=world.width-1||y>=world.height-1||world.blocked[y*world.width+x])return false;move={fromX:player.x,fromY:player.y,x,y,p:0};player.dir=x>player.x?'right':x<player.x?'left':y>player.y?'down':'up';return true}
 function openAt(x,y){const radius=.18;return [[-radius,-radius],[radius,-radius],[-radius,radius],[radius,radius]].every(([dx,dy])=>{const xx=Math.round(x+dx),yy=Math.round(y+dy);return xx>0&&yy>0&&xx<world.width-1&&yy<world.height-1&&!world.blocked[yy*world.width+xx]})}
 function moved(distance){if(distance<=0)return;if(world.interior){state.room.x=player.x;state.room.y=player.y}else{state.x=player.x;state.y=player.y}state.steps+=distance;const hpBefore=state.hp,used=Travel.advance(state,distance,!!world.interior);if(!state.hp){gameOver('行軍斷糧，生命已耗盡。每不足 1 糧的路程會損耗 2 生命。');return}if(used){if(state.hp<hpBefore)toast('行軍斷糧，損耗 '+(hpBefore-state.hp)+' 生命。請使用乾糧、狩獵或回營補給。');else if(!state.food)toast('糧食已用完：再走一份糧食的路程將損耗 2 生命。');save()}update()}
 function frame(ms){const dt=Math.min(.05,(ms-last)/1000||.016);last=ms;if(running){player.moving=false;if(!paused()){
  encounterCooldown=Math.max(0,encounterCooldown-dt);let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),right=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);if(!forward&&!right&&(stick.x||stick.y)){right=stick.x;forward=-stick.y}
  if(forward||right){route=[];target=null;move=null;const len=Math.hypot(forward,right);forward/=len;right/=len;const yaw=Renderer.yaw,dx=(Math.sin(yaw)*forward-Math.cos(yaw)*right)*dt*7.5,dy=(Math.cos(yaw)*forward+Math.sin(yaw)*right)*dt*7.5;const oldX=player.x,oldY=player.y;if(openAt(player.x+dx,player.y))player.x+=dx;if(openAt(player.x,player.y+dy))player.y+=dy;const d=Math.hypot(player.x-oldX,player.y-oldY);if(d){player.yaw=Math.atan2(player.x-oldX,player.y-oldY);player.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');player.moving=true;moved(d)}}
  else{let budget=dt*7.5;while(budget>1e-8&&!paused()){
   if(!move){if(route.length){const next=route.shift();if(world.blocked[next.y*world.width+next.x]){route=[];break}const distance=Math.hypot(next.x-player.x,next.y-player.y);move={x:next.x,y:next.y,distance};if(distance<1e-6){move=null;continue}}
    else if(target){const e=target;if(Math.hypot(e.x-player.x,e.y-player.y)<(e.interactionRange??1.6)){target=null;interact(e);break}else{const choices=World.path(world,player,e);if(!choices.length){target=null;break}route=choices;continue}}else break}
   const oldX=player.x,oldY=player.y,d=Math.hypot(move.x-oldX,move.y-oldY);if(d<1e-7){move=null;continue}const amount=Math.min(budget,d),dx=(move.x-oldX)/d*amount,dy=(move.y-oldY)/d*amount;player.x+=dx;player.y+=dy;player.yaw=Math.atan2(dx,dy);player.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');player.moving=true;budget-=amount;moved(amount);if(state.gameOver)break;if(amount>=d-1e-7){player.x=move.x;player.y=move.y;move=null}
  }}
  if(!paused())Ecology.updatePeople(world,player,dt,{target,active:state.active});if(!paused()&&!world.interior){const contact=Ecology.update(world,player,dt,e=>flag(e.id),encounterCooldown>0);if(contact)interact(contact)}
  nearest=Renderer.visible(world,state).map(e=>({e,d:Math.hypot(e.x-player.x,e.y-player.y)})).filter(v=>v.d<(v.e.interactionRange??2.1)).sort((a,b)=>a.d-b.d)[0]?.e;$('interact-hint').textContent=nearest?(nearest.entrance?'E / 進入 · ':nearest.type==='room-exit'?'E / 離開 · ':'E / 互動 · ')+nearest.name:'';$('travel-indicator').hidden=!route.length;
 }GearView.animate(player.moving&&settings.motion,ms/1000);Renderer.draw(world,state,player,settings.motion?ms/1000:0,route)}requestAnimationFrame(frame)}
 MediaGallery.init({beforeOpen(){keys.clear();stick={x:0,y:0};$('stick').style.transform='';cameraDrag=null;releaseMouse()},afterClose(){captureMouse()}});
 $('pause-music').onclick=MediaGallery.openMusic;$('pause-mv').onclick=MediaGallery.openMV;
